void AuxOrganizationWindowController::PublishTitle(tabs::TabHandle handle) {
  auto* service = Current() ? Organization(browser_.get()) : nullptr;
  auto* tab = handle.Get();
  if (!service || service->blocked() || !tab || model_->GetIndexOfTab(tab) < 0 ||
      !tab->GetContents() || tab->GetContents()->GetBrowserContext() != profile_) return;
  if (service->pending()) { dirty_titles_.insert(handle); return; }
  const auto* identity = PageIdentity::FromWebContents(tab->GetContents());
  if (IsBookmarkTabExcluded(tab, model_) || (identity && identity->runtime_owned()) ||
      (!tab->IsPinned() && (!ordinary_eligible_ || !ordinary_eligible_.Run(*tab)))) return;
  const auto view = views_.find(handle);
  if (view == views_.end() || view->second.document_id.empty() ||
      !view->second.pending_shared_url.empty() || dirty_navigation_.contains(handle)) return;
  const auto found = service->snapshot().entries.find(view->second.logical_id);
  if (found == service->snapshot().entries.end() || found->second.archived ||
      found->second.title_mode != organization::TitleMode::kAutomatic ||
      GetRememberedPinnedTabEntryId(*tab->GetContents()) != found->first) return;
  const auto url = LogicalTabUrl(*tab->GetContents());
  const auto title = base::UTF16ToUTF8(tab->GetContents()->GetTitle());
  if (!url.is_valid() || url.spec() != found->second.current_url ||
      url.spec() != view->second.loaded_url || title.empty() || title.size() > 4096 ||
      title == found->second.title) return;
  auto context = CaptureOrganizationContext(*browser_);
  if (!context) { dirty_titles_.insert(handle); return; }
  const auto id = found->first, document = view->second.document_id;
  const auto generation = context->owner_generation;
  organization::Command command; command.action = organization::Action::kUpdateAutomaticTitle;
  command.id = id; command.url = url.spec(); command.title = title;
  // CaptureOrganizationContext plus the native document check above are on
  // this UI sequence; the model also checks revision, URL and automatic mode.
  service->RecordTabTitles(std::move(*context), {std::move(command)}, base::BindOnce(
      [](base::WeakPtr<AuxOrganizationWindowController> owner, tabs::TabHandle target,
         std::string logical, std::string captured_document, std::string captured_url,
         std::string captured_title, std::string expected_generation,
         organization::CommitResult result) {
        if (!owner || !owner->Current()) return;
        auto* coordinator = organization::OrganizationProfileServiceFactory::GetForProfileIfExists(owner->profile_);
        if (!coordinator || coordinator->owner_generation() != expected_generation ||
            !coordinator->model() || coordinator->model()->blocked()) return;
        auto* current_tab = target.Get();
        const auto live = owner->views_.find(target);
        if (!current_tab || owner->model_->GetIndexOfTab(current_tab) < 0 || !current_tab->GetContents() ||
            live == owner->views_.end() || live->second.logical_id != logical ||
            GetRememberedPinnedTabEntryId(*current_tab->GetContents()) != logical) return;
        // A newer document/title can arrive during storage. Never replay the
        // captured string: queue a fresh native read guarded by the new shared
        // URL/revision. A different logical/profile owner is never touched.
        if (result.error == organization::Error::kBusy || result.error == organization::Error::kStaleRevision ||
            (result.error == organization::Error::kNone &&
             (live->second.document_id != captured_document ||
              LogicalTabUrl(*current_tab->GetContents()).spec() != captured_url ||
              base::UTF16ToUTF8(current_tab->GetContents()->GetTitle()) != captured_title)))
          owner->dirty_titles_.insert(target);
        owner->QueueReconcile();
      }, weak_.GetWeakPtr(), handle, id, document, url.spec(), title, generation));
}
