TEST(OrganizationModel, TitleMigrationPreservesUnknownAndManualNames) {
  auto created = Run(Initial(), Create(Action::kCreateTab, kTab));
  ASSERT_EQ(created.error, Error::kNone);
  auto legacy = EncodeSnapshot(created.snapshot);
  legacy.Set("schemaVersion", 1);
  legacy.FindList("entries")->front().GetDict().Remove("titleMode");
  auto decoded = DecodeSnapshot(legacy, created.snapshot.profile_id);
  ASSERT_TRUE(decoded.snapshot);
  EXPECT_EQ(decoded.snapshot->schema_version, 2u);
  EXPECT_EQ(decoded.snapshot->entries.at(kTab).title, "Entry");
  EXPECT_EQ(decoded.snapshot->entries.at(kTab).title_mode, TitleMode::kLegacyPreserved);
  Command title; title.action = Action::kUpdateAutomaticTitle; title.id = kTab;
  title.url = created.snapshot.entries.at(kTab).current_url; title.title = "Page title";
  EXPECT_EQ(Run(*decoded.snapshot, title, 2).error, Error::kInvalid);
  auto rewritten = EncodeSnapshot(*decoded.snapshot);
  EXPECT_EQ(rewritten.FindInt("schemaVersion"), 2);
  EXPECT_EQ(*rewritten.FindList("entries")->front().GetDict().FindString("titleMode"), "legacy-preserved");
  rewritten.FindList("entries")->front().GetDict().Set("titleMode", "unknown-future-mode");
  EXPECT_FALSE(DecodeSnapshot(rewritten, created.snapshot.profile_id).snapshot);
  rewritten = EncodeSnapshot(*decoded.snapshot); rewritten.Set("schemaVersion", 3);
  EXPECT_FALSE(DecodeSnapshot(rewritten, created.snapshot.profile_id).snapshot);
  legacy.FindList("entries")->front().GetDict().Set("titleMode", "automatic");
  EXPECT_FALSE(DecodeSnapshot(legacy, created.snapshot.profile_id).snapshot);
}
TEST(OrganizationModel, AutomaticTitleRequiresExactUrlAndManualRenameWins) {
  auto create = Create(Action::kCreateTab, kTab);
  const auto prior_fingerprint = Fingerprint(create);
  create.title_mode = TitleMode::kAutomatic;
  EXPECT_NE(Fingerprint(create), prior_fingerprint);
  auto created = Run(Initial(), create);
  ASSERT_EQ(created.error, Error::kNone);
  Command title; title.action = Action::kUpdateAutomaticTitle; title.id = kTab;
  title.url = "https://example.test/other"; title.title = "New page title";
  EXPECT_EQ(Run(created.snapshot, title, 2).error, Error::kInvalid);
  title.url = create.url;
  auto updated = Run(created.snapshot, title, 2);
  ASSERT_EQ(updated.error, Error::kNone);
  EXPECT_EQ(updated.snapshot.entries.at(kTab).title, "New page title");
  Command rename; rename.action = Action::kRenameEntry; rename.id = kTab;
  rename.title = "My permanent label";
  auto named = Run(updated.snapshot, rename, 3);
  ASSERT_EQ(named.error, Error::kNone);
  EXPECT_EQ(named.snapshot.entries.at(kTab).title_mode, TitleMode::kManual);
  EXPECT_EQ(Run(named.snapshot, title, 4).error, Error::kInvalid);
  auto roundtrip = DecodeSnapshot(EncodeSnapshot(named.snapshot), named.snapshot.profile_id);
  ASSERT_TRUE(roundtrip.snapshot);
  EXPECT_EQ(*roundtrip.snapshot, named.snapshot);
  create.title_mode.reset();
  EXPECT_EQ(Fingerprint(create), prior_fingerprint);
}
